import { randomBytes, createHash, timingSafeEqual } from 'node:crypto';
// 1. Cryptographic PKCE Helper (RFC 7636)
export class PKCEHelper {
  public static generatePKCEPair(length: number = 64) {
    if (length < 43 || length > 128) throw new RangeError('Verifier length 43-128');
    const unreserved = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~';
    const bytes = randomBytes(length);
    let codeVerifier = '';
    for (let i = 0; i < length; i++) codeVerifier += unreserved[bytes[i] % unreserved.length];
    const codeChallenge = createHash('sha256').update(codeVerifier, 'utf8').digest('base64url');
    return { codeVerifier, codeChallenge, method: 'S256' as const };
  }
  public static verifyCodeChallenge(verifier: string, storedChallenge: string): boolean {
    const computed = createHash('sha256').update(verifier, 'utf8').digest('base64url');
    const bufA = Buffer.from(computed, 'utf8');
    const bufB = Buffer.from(storedChallenge, 'utf8');
    return bufA.length === bufB.length && timingSafeEqual(bufA, bufB);
  }
}
// 2. JWT Claim Verification & Tenant Guard
export interface EnterpriseJWTPayload {
  iss: string; sub: string; aud: string | string[]; exp: number; tenant_id: string; roles: string[];
}
export class JWTClaimValidator {
  public static validateClaims(rawToken: string, expectedIss: string, expectedAud: string): EnterpriseJWTPayload {
    const parts = rawToken.split('.');
    if (parts.length !== 3) throw new Error('Invalid JWT format');
    const payload: EnterpriseJWTPayload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
    const now = Math.floor(Date.now() / 1000);
    if (now >= payload.exp) throw new Error('Token expired');
    if (payload.iss !== expectedIss) throw new Error('Invalid issuer');
    const audMatch = Array.isArray(payload.aud) ? payload.aud.includes(expectedAud) : payload.aud === expectedAud;
    if (!audMatch) throw new Error('Invalid audience');
    if (!payload.tenant_id) throw new Error('Missing tenant_id claim');
    return payload;
  }
}
